const name = fs.readFileSync(0, 'utf-8').trim();
console.log(`GREETINGS, ${name.toUpperCase()}!`);

stages.lessonContentMd:
## Conditionals in JavaScript

```javascript
const score = 85;
if (score >= 70) {
  console.log("PASS");
} else {
  console.log("FAIL");
}
```

stages.starterCode:
const fs = require('fs');
const n = parseInt(fs.readFileSync(0, 'utf-8').trim(), 10);
// Check condition

stages.solutionCode:
const fs = require('fs');
const n = parseInt(fs.readFileSync(0, 'utf-8').trim(), 10);
if (n >= 50) {
  console.log("PASS");
} else {
  console.log("FAIL");
}

stages.lessonContentMd:
## Strict Equality & Logical Operators

Always use `===` for strict comparison (checks type and value).

```javascript
if (role === "admin" && status === "active") {
  console.log("FULL ACCESS");
}
```

stages.starterCode:
const fs = require('fs');
const [role, status] = fs.readFileSync(0, 'utf-8').trim().split(/\s+/);
// Evaluate authentication

stages.solutionCode:
const fs = require('fs');
const [role, status] = fs.readFileSync(0, 'utf-8').trim().split(/\s+/);
if (role === "admin" && status === "active") {
  console.log("GRANTED");
} else {
  console.log("DENIED");
}

stages.lessonContentMd:
## For Loops in JavaScript

A `for` loop repeatedly executes a block of code a set number of times using an initializer, a condition, and a final expression.

```javascript
for (let i = 1; i <= 3; i++) {
  console.log(i);
}
```

stages.starterCode:
const fs = require('fs');
const n = parseInt(fs.readFileSync(0, 'utf-8').trim(), 10);
// Run loop from 1 to n

stages.solutionCode:
const fs = require('fs');
const n = parseInt(fs.readFileSync(0, 'utf-8').trim(), 10);
for (let i = 1; i <= n; i++) {
  console.log(i);
}

stages.lessonContentMd:
## While Loops

```javascript
let count = 5;
while (count > 0) {
  console.log(count);
  count--;
}
```

stages.starterCode:
const fs = require('fs');
let n = parseInt(fs.readFileSync(0, 'utf-8').trim(), 10);
// Implement while loop

stages.solutionCode:
const fs = require('fs');
let n = parseInt(fs.readFileSync(0, 'utf-8').trim(), 10);
while (n > 0) {
  n = Math.floor(n / 2);
  console.log(n);
}

