}

stages.lessonContentMd:
## Array Push & Join

```javascript
const list = [];
list.push("A");
list.push("B");
console.log(list.join("-")); // "A-B"
```

stages.starterCode:
const fs = require('fs');
const nums = fs.readFileSync(0, 'utf-8').trim().split(/\s+/).map(Number);
// Build new array with push and join

stages.solutionCode:
const fs = require('fs');
const nums = fs.readFileSync(0, 'utf-8').trim().split(/\s+/).map(Number);
const result = [];
for (const n of nums) {
  result.push(n + 1);
}
console.log(result.join(' '));

stages.lessonContentMd:
## Functions in JavaScript

```javascript
function multiply(a, b) {
  return a * b;
}
console.log(multiply(6, 7)); // 42
```

