stages.lessonContentMd:
## Objects in JavaScript

```javascript
const user = { name: "Alice", score: 100 };
console.log(user.name);
console.log(user["score"]);
```

stages.starterCode:
const fs = require('fs');
const [name, xpStr] = fs.readFileSync(0, 'utf-8').trim().split(/\s+/);
// Construct object and print format

stages.solutionCode:
const fs = require('fs');
const [name, xpStr] = fs.readFileSync(0, 'utf-8').trim().split(/\s+/);
const obj = { name, xp: parseInt(xpStr, 10) };
console.log(`${obj.name}:${obj.xp}`);

stages.starterCode:
const fs = require('fs');
const nums = fs.readFileSync(0, 'utf-8').trim().split(/\s+/).map(Number);
// Use .filter() and print space-separated

stages.solutionCode:
const fs = require('fs');
const nums = fs.readFileSync(0, 'utf-8').trim().split(/\s+/).map(Number);
const filtered = nums.filter(x => x > 10);
console.log(filtered.join(' '));

stages.starterCode:
const fs = require('fs');
const nums = fs.readFileSync(0, 'utf-8').trim().split(/\s+/).map(Number);
// Use .map() to square numbers and print space-separated

stages.solutionCode:
const fs = require('fs');
const nums = fs.readFileSync(0, 'utf-8').trim().split(/\s+/).map(Number);
const squared = nums.map(x => x * x);
console.log(squared.join(' '));
